            ["en_MY"] = AstRule,
            ["en_NZ"] = AstRule,
            ["en_SG"] = AstRule,
            ["en_US"] = AstRule,
            ["en_ZA"] = AstRule,
            ["es"] = EsRule,
            ["es_419"] = EsRule,
            ["es_ES"] = EsRule,
            ["es_MX"] = EsRule,
            ["es_US"] = EsRule,
            ["et"] = AstRule,
            ["eu"] = AfRule,
            ["fa"] = AmRule,
            ["fi"] = AstRule,
            ["fil"] = CebRule,
            ["fr"] = FrRule,
            ["fr_CA"] = FrRule,
            ["fr_CH"] = FrRule,
            ["fur"] = AfRule,
            ["ga"] = GaRule,
            ["gl"] = AstRule,
            ["gsw"] = AfRule,
            ["gu"] = AmRule,
            ["haw"] = AfRule,
            ["he"] = HeRule,
            ["hi"] = AmRule,
            ["hr"] = BsRule,
            ["hu"] = AfRule,
            ["hy"] = FfRule,
            ["id"] = DefaultRule,
            ["in"] = DefaultRule,
            ["is"] = IsRule,
            ["it"] = CaRule,
            ["it_CH"] = CaRule,
            ["iw"] = HeRule,
            ["ja"] = DefaultRule,
            ["ka"] = AfRule,
            ["kk"] = AfRule,
            ["km"] = DefaultRule,
