            ["pl"] = PlRule,
            ["ps"] = AfRule,
            ["pt"] = PtRule,
            ["pt_BR"] = PtRule,
            ["pt_PT"] = CaRule,
            ["ro"] = MoRule,
            ["ru"] = RuRule,
            ["si"] = SiRule,
            ["sk"] = CsRule,
            ["sl"] = SlRule,
            ["sq"] = AfRule,
            ["sr"] = BsRule,
            ["sr_Latn"] = BsRule,
